def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count ordered paths of K moves through distinct empty grid cells.

    Moves go up, down, left, or right. Every empty cell is a possible
    starting point, and a cell cannot appear twice in one path.
    H and W are at most 10 and K is at most 11.
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == '.']
    if len(cells) <= K:
        return 0
    indices = {cell: i for i, cell in enumerate(cells)}
    adjacent = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = indices.get((r + dr, c + dc))
            if j is not None:
                adjacent[i].append(j)

    visited = [False] * len(cells)

    def walk(cell: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for neighbor in adjacent[cell]:
            if not visited[neighbor]:
                visited[neighbor] = True
                total += walk(neighbor, remaining - 1)
                visited[neighbor] = False
        return total

    total = 0
    for start in range(len(cells)):
        visited[start] = True
        total += walk(start, K)
        visited[start] = False
    return total

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions and replacements can turn s into t
    using at most k operations (k <= 20, string lengths <= 500000).
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if max(n, m) <= k:
        return True

    # A diagonal is i - j. Keep its furthest source position after each
    # edit budget, extending every state through all following equal letters.
    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    if i == n and i == m:
        return True
    previous = {0: i}

    for edits in range(1, k + 1):
        current = {}
        for diagonal in range(max(-edits, -m), min(edits, n) + 1):
            best = -1

            # Replace a character; both indices advance.
            source = previous.get(diagonal, -1)
            if 0 <= source < n and source - diagonal < m:
                best = source + 1

            # Delete from s; only the source index advances.
            source = previous.get(diagonal - 1, -1)
            if 0 <= source < n:
                best = max(best, source + 1)

            # Insert into s; only the target index advances.
            source = previous.get(diagonal + 1, -1)
            if source >= 0 and source - diagonal - 1 < m:
                best = max(best, source)

            if best < 0:
                continue
            target = best - diagonal
            while best < n and target < m and s[best] == t[target]:
                best += 1
                target += 1
            if best == n and target == m:
                return True
            current[diagonal] = best
        previous = current
    return False

