from math import isqrt


def find_largest_400_number(a: int) -> int:
    """Find the largest 400 number not exceeding a.

    A 400 number has exactly two distinct prime factors, each with an
    even exponent. The supported range is 36 <= a <= 10**12.

    Such numbers are precisely squares whose roots have exactly two
    distinct prime factors. In particular, the answer for 404 is 400.
    """
    root = isqrt(a)
    while root >= 6:
        remaining = root
        distinct = 0
        if remaining % 2 == 0:
            distinct += 1
            while remaining % 2 == 0:
                remaining //= 2
        divisor = 3
        while divisor * divisor <= remaining:
            if remaining % divisor == 0:
                distinct += 1
                while remaining % divisor == 0:
                    remaining //= divisor
                if distinct > 2:
                    break
            divisor += 2
        if remaining > 1:
            distinct += 1
        if distinct == 2:
            return root * root
        root -= 1
    return 36

# The scalar implementation is retained below for environments without a C++
# compiler. The optional native kernel runs the identical residue sieve and
# multiplicative summation, avoiding Python loop overhead at N=10**10.
_NATIVE_SOURCE = r'''
#include <vector>
#include <cmath>
#include <utility>
#include <cstdint>
using ll = long long;
static const ll MOD=998244353;
struct Solver {
    ll n, m;
    int root, size;
    std::vector<int> primes, prefix;
    std::vector<ll> values, one, two, w;
    int index(ll x) const { return x<=root ? size-int(x) : int(n/x)-1; }
    ll power(ll a,ll b) {
        ll r=1;
        for(;b;b>>=1,a=a*a%MOD) if(b&1)r=r*a%MOD;
        return r;
    }
    bool allowed(int r,int e) const {
        return r==0 || (r==1 ? e%3!=2 : e%2==0);
    }
    std::pair<ll,ll> sum(ll x,int start) {
        if(start<(int)primes.size() && primes[start]>x) return {0,0};
        int k=index(x);
        ll total=m*(one[k]+two[k]+(x>=3)-start)%MOD;
        ll bad=m*(one[k]+(x>=3)-prefix[start])%MOD;
        for(int i=start;i<(int)primes.size();++i) {
            ll p=primes[i];
            if(p*p>x) break;
            int r=p%3, e=1;
            for(ll q=x/p;q>=p;q/=p,++e) {
                auto child=sum(q,i+1);
                total=(total+w[e]*child.first+w[e+1])%MOD;
                if(allowed(r,e))bad=(bad+w[e]*child.second)%MOD;
                if(allowed(r,e+1))bad=(bad+w[e+1])%MOD;
            }
        }
        return {total,bad};
    }
    ll solve(ll N,ll M) {
        n=N;m=M;
        if(n<2)return 0;
        root=(int)std::sqrt((long double)n);
        while((ll)(root+1)*(root+1)<=n)++root;
        while((ll)root*root>n)--root;
        std::vector<char> sieve(root+1,0);
        for(int p=2;p<=root;++p) {
            if(sieve[p])continue;
            primes.push_back(p);
            if((ll)p*p<=root)
                for(int j=p*p;j<=root;j+=p)sieve[j]=1;
        }
        for(int i=1;i<=root;++i)values.push_back(n/i);
        for(ll i=n/(root+1);i>=1;--i)values.push_back(i);
        size=values.size();
        for(ll v:values) {
            one.push_back((v+2)/3-1);
            two.push_back((v+1)/3);
        }
        for(ll p:primes) {
            if(p==3)continue;
            ll square=p*p;
            int base=index(p-1);
            ll a=one[base],b=two[base];
            for(int i=0;i<size && values[i]>=square;++i) {
                int k=index(values[i]/p);
                if(p%3==1) {
                    one[i]-=one[k]-a;
                    two[i]-=two[k]-b;
                } else {
                    one[i]-=two[k]-b;
                    two[i]-=one[k]-a;
                }
            }
        }
        prefix.push_back(0);
        for(int p:primes)prefix.push_back(prefix.back()+(p%3!=2));
        w.push_back(1);
        for(int e=1;(1LL<<e)<=n;++e)
            w.push_back(w.back()*(m+e-1)%MOD*power(e,MOD-2)%MOD);
        auto result=sum(n,0);
        return (result.first-result.second+MOD)%MOD;
    }
};
extern "C" long long count_sequences(long long n,long long m) {
    return Solver().solve(n,m);
}
'''
_native_library = None
_native_attempted = False


def _native_kernel():
    global _native_library, _native_attempted
    if not _native_attempted:
        _native_attempted = True
        import ctypes
        import os
        import shutil
        import subprocess
        import tempfile
        compiler = shutil.which("g++") or shutil.which("c++")
        if compiler:
            try:
                with tempfile.TemporaryDirectory(prefix="good_sequences_") as directory:
                    library_path = os.path.join(directory, "kernel.so")
                    subprocess.run(
                        [compiler, "-O3", "-std=c++17", "-shared", "-fPIC",
                         "-x", "c++", "-", "-o", library_path],
                        input=_NATIVE_SOURCE, text=True, capture_output=True,
                        check=True, timeout=15,
                    )
                    _native_library = ctypes.CDLL(library_path)
                    _native_library.count_sequences.argtypes = [ctypes.c_longlong, ctypes.c_longlong]
                    _native_library.count_sequences.restype = ctypes.c_longlong
            except (OSError, subprocess.SubprocessError):
                _native_library = None
    return _native_library


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive sequences whose product is <= N and whose
    product has divisor sum divisible by 3, modulo 998244353.

    Bounds: 1 <= N <= 10**10, 1 <= M <= 10**5.
    """
    if N >= 10000:
        kernel = _native_kernel()
        if kernel is not None:
            return kernel.count_sequences(N, M)
    return _count_python(N, M)

from math import isqrt


def _count_python(N: int, M: int) -> int:
    """Count length-M positive integer sequences with product <= N and
    divisor sum divisible by 3, modulo 998244353.
    """
    mod = 998244353
    if N < 2:
        return 0
    limit = isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[:2] = b"\x00\x00"
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            sieve[p * p:limit + 1:p] = b"\x00" * ((limit - p * p) // p + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]
    values = [N // i for i in range(1, limit + 1)]
    values.extend(range(N // (limit + 1), 0, -1))
    size = len(values)
    # Prime counting tables for the two nonzero residue classes modulo 3.
    one = [(v + 2) // 3 - 1 for v in values]
    two = [(v + 1) // 3 for v in values]
    try:
        import numpy as np
    except ImportError:
        np = None
    if np is not None and N >= 1000000:
        vs = np.array(values, dtype=np.int64)
        aa = np.array(one, dtype=np.int64)
        bb = np.array(two, dtype=np.int64)
        for p in primes:
            if p == 3:
                continue
            end = min(limit, N // (p * p))
            if p * p <= limit:
                end = size - p * p + 1
            q = vs[:end] // p
            k = np.where(q <= limit, size - q, N // q - 1)
            base = size - (p - 1)
            da = aa[k] - aa[base]
            db = bb[k] - bb[base]
            if p % 3 == 1:
                aa[:end] -= da
                bb[:end] -= db
            else:
                aa[:end] -= db
                bb[:end] -= da
        one, two = aa.tolist(), bb.tolist()
    for p in ([] if np is not None and N >= 1000000 else primes):
        if p == 3:
            continue
        square = p * p
        base = size - (p - 1)
        a, b = one[base], two[base]
        if p % 3 == 1:
            for i, v in enumerate(values):
                if v < square:
                    break
                q = v // p
                k = size - q if q <= limit else N // q - 1
                one[i] -= one[k] - a
                two[i] -= two[k] - b
        else:
            for i, v in enumerate(values):
                if v < square:
                    break
                q = v // p
                k = size - q if q <= limit else N // q - 1
                one[i] -= two[k] - b
                two[i] -= one[k] - a
    prefix = [0]
    for p in primes:
        prefix.append(prefix[-1] + (p % 3 != 2))
    weights = [1]
    for e in range(1, N.bit_length()):
        weights.append(weights[-1] * (M + e - 1) * pow(e, mod - 2, mod) % mod)

    def sums(x, start):
        if start < len(primes) and primes[start] > x:
            return 0, 0
        k = size - x if x <= limit else N // x - 1
        total = M * (one[k] + two[k] + (x >= 3) - start)
        bad = M * (one[k] + (x >= 3) - prefix[start])
        for i in range(start, len(primes)):
            p = primes[i]
            if p * p > x:
                break
            q = x // p
            e = 1
            residue = p % 3
            while q >= p:
                if i + 1 == len(primes) or primes[i + 1] * primes[i + 1] > q:
                    k = size - q if q <= limit else N // q - 1
                    child_total = M * (one[k] + two[k] + (q >= 3) - i - 1)
                    child_bad = M * (one[k] + (q >= 3) - prefix[i + 1])
                else:
                    child_total, child_bad = sums(q, i + 1)
                total += weights[e] * child_total + weights[e + 1]
                allowed = residue == 0 or (residue == 1 and e % 3 != 2) or (residue == 2 and e % 2 == 0)
                next_allowed = residue == 0 or (residue == 1 and (e + 1) % 3 != 2) or (residue == 2 and (e + 1) % 2 == 0)
                if allowed:
                    bad += weights[e] * child_bad
                if next_allowed:
                    bad += weights[e + 1]
                q //= p
                e += 1
            total %= mod
            bad %= mod
        return total % mod, bad % mod

    total, bad = sums(N, 0)
    return (total - bad) % mod

