+_NATIVE_SOURCE = r'''
+#include <vector>
+#include <cmath>
+#include <utility>
+#include <cstdint>
+using ll = long long;
+static const ll MOD=998244353;
+struct Solver {
+    ll n, m;
+    int root, size;
+    std::vector<int> primes, prefix;
+    std::vector<ll> values, one, two, w;
+    int index(ll x) const { return x<=root ? size-int(x) : int(n/x)-1; }
+    ll power(ll a,ll b) {
+        ll r=1;
+        for(;b;b>>=1,a=a*a%MOD) if(b&1)r=r*a%MOD;
+        return r;
+    }
+    bool allowed(int r,int e) const {
+        return r==0 || (r==1 ? e%3!=2 : e%2==0);
+    }
+    std::pair<ll,ll> sum(ll x,int start) {
+        if(start<(int)primes.size() && primes[start]>x) return {0,0};
+        int k=index(x);
+        ll total=m*(one[k]+two[k]+(x>=3)-start)%MOD;
+        ll bad=m*(one[k]+(x>=3)-prefix[start])%MOD;
+        for(int i=start;i<(int)primes.size();++i) {
+            ll p=primes[i];
+            if(p*p>x) break;
+            int r=p%3, e=1;
+            for(ll q=x/p;q>=p;q/=p,++e) {
+                auto child=sum(q,i+1);
+                total=(total+w[e]*child.first+w[e+1])%MOD;
+                if(allowed(r,e))bad=(bad+w[e]*child.second)%MOD;
+                if(allowed(r,e+1))bad=(bad+w[e+1])%MOD;
+            }
+        }
+        return {total,bad};
+    }
+    ll solve(ll N,ll M) {
+        n=N;m=M;
+        if(n<2)return 0;
+        root=(int)std::sqrt((long double)n);
+        while((ll)(root+1)*(root+1)<=n)++root;
+        while((ll)root*root>n)--root;
+        std::vector<char> sieve(root+1,0);
+        for(int p=2;p<=root;++p) {
+            if(sieve[p])continue;
+            primes.push_back(p);
+            if((ll)p*p<=root)
