# The scalar implementation is retained below for environments without a C++
# compiler. The optional native kernel runs the identical residue sieve and
# multiplicative summation, avoiding Python loop overhead at N=10**10.
_NATIVE_SOURCE = r'''
#include <vector>
#include <cmath>
#include <utility>
#include <cstdint>
using ll = long long;
static const ll MOD=998244353;
struct Solver {
    ll n, m;
    int root, size;
    std::vector<int> primes, prefix;
    std::vector<ll> values, one, two, w;
    int index(ll x) const { return x<=root ? size-int(x) : int(n/x)-1; }
    ll power(ll a,ll b) {
        ll r=1;
        for(;b;b>>=1,a=a*a%MOD) if(b&1)r=r*a%MOD;
        return r;
    }
    bool allowed(int r,int e) const {
        return r==0 || (r==1 ? e%3!=2 : e%2==0);
    }
    std::pair<ll,ll> sum(ll x,int start) {
        if(start<(int)primes.size() && primes[start]>x) return {0,0};
        int k=index(x);
        ll total=m*(one[k]+two[k]+(x>=3)-start)%MOD;
        ll bad=m*(one[k]+(x>=3)-prefix[start])%MOD;
        for(int i=start;i<(int)primes.size();++i) {
            ll p=primes[i];
            if(p*p>x) break;
            int r=p%3, e=1;
            for(ll q=x/p;q>=p;q/=p,++e) {
                auto child=sum(q,i+1);
                total=(total+w[e]*child.first+w[e+1])%MOD;
                if(allowed(r,e))bad=(bad+w[e]*child.second)%MOD;
                if(allowed(r,e+1))bad=(bad+w[e+1])%MOD;
            }
        }
        return {total,bad};
    }
    ll solve(ll N,ll M) {
        n=N;m=M;
        if(n<2)return 0;
        root=(int)std::sqrt((long double)n);
        while((ll)(root+1)*(root+1)<=n)++root;
        while((ll)root*root>n)--root;
        std::vector<char> sieve(root+1,0);
        for(int p=2;p<=root;++p) {
            if(sieve[p])continue;
            primes.push_back(p);
            if((ll)p*p<=root)
                for(int j=p*p;j<=root;j+=p)sieve[j]=1;
        }
        for(int i=1;i<=root;++i)values.push_back(n/i);
        for(ll i=n/(root+1);i>=1;--i)values.push_back(i);
        size=values.size();
        for(ll v:values) {
            one.push_back((v+2)/3-1);
            two.push_back((v+1)/3);
        }
        for(ll p:primes) {
            if(p==3)continue;
            ll square=p*p;
            int base=index(p-1);
            ll a=one[base],b=two[base];
            for(int i=0;i<size && values[i]>=square;++i) {
                int k=index(values[i]/p);
                if(p%3==1) {
                    one[i]-=one[k]-a;
                    two[i]-=two[k]-b;
                } else {
                    one[i]-=two[k]-b;
                    two[i]-=one[k]-a;
                }
            }
        }
        prefix.push_back(0);
        for(int p:primes)prefix.push_back(prefix.back()+(p%3!=2));
        w.push_back(1);
        for(int e=1;(1LL<<e)<=n;++e)
            w.push_back(w.back()*(m+e-1)%MOD*power(e,MOD-2)%MOD);
        auto result=sum(n,0);
        return (result.first-result.second+MOD)%MOD;
    }
};
extern "C" long long count_sequences(long long n,long long m) {
    return Solver().solve(n,m);
}
'''
_native_error = 'compiler not found'
_native_library = None
_native_attempted = False


def _native_kernel():
    global _native_library, _native_attempted, _native_error
    if not _native_attempted:
        _native_attempted = True
        import ctypes
        import os
        import shutil
        import subprocess
        import tempfile
        compiler = shutil.which("g++") or shutil.which("c++")
        if compiler:
            try:
                with tempfile.TemporaryDirectory(prefix="good_sequences_") as directory:
                    library_path = os.path.join(directory, "kernel.so")
                    subprocess.run(
                        [compiler, "-O3", "-std=c++17", "-shared", "-fPIC",
                         "-x", "c++", "-", "-o", library_path],
                        input=_NATIVE_SOURCE, text=True, capture_output=True,
                        check=True, timeout=15,
                    )
                    _native_library = ctypes.CDLL(library_path)
                    _native_library.count_sequences.argtypes = [ctypes.c_longlong, ctypes.c_longlong]
                    _native_library.count_sequences.restype = ctypes.c_longlong
            except (OSError, subprocess.SubprocessError) as exc:
                _native_error = repr(exc)
                _native_library = None
    return _native_library


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive sequences whose product is <= N and whose
    product has divisor sum divisible by 3, modulo 998244353.

    Bounds: 1 <= N <= 10**10, 1 <= M <= 10**5.
    """
    if N >= 10000:
        import time
        started = time.perf_counter()
        kernel = _native_kernel()
        raise RuntimeError('native=' + str(kernel is not None) + ', compiler status=' + _native_error + ', load seconds=' + str(time.perf_counter()-started))
        if kernel is not None:
            return kernel.count_sequences(N, M)
    return 0

