def _load_kernel():
    global _kernel, _native_error
    if _kernel is not None or _native_error is not None:
        return _kernel
    import ctypes
    import os
    import shutil
    import subprocess
    import tempfile
    compiler = shutil.which("gcc") or shutil.which("cc")
    if compiler is None:
        _native_error = "C compiler unavailable"
        return None
    try:
        with tempfile.TemporaryDirectory(prefix="good_sequences_") as directory:
            path = os.path.join(directory, "kernel.so")
            subprocess.run(
                [compiler, "-O3", "-shared", "-fPIC", "-x", "c", "-", "-o", path, "-lm"],
                input=_C_SOURCE, text=True, capture_output=True, check=True, timeout=3,
            )
            library = ctypes.CDLL(path)
            library.count_sequences.argtypes = [ctypes.c_longlong, ctypes.c_longlong]
            library.count_sequences.restype = ctypes.c_longlong
            _kernel = library
    except (OSError, subprocess.SubprocessError) as exc:
        _native_error = getattr(exc, "stderr", None) or str(exc)
    return _kernel


def _python_count(N, M):
    mod = 998244353
    root = isqrt(N)
    sieve = bytearray(root+1)
    for p in range(2, isqrt(root)+1):
        if not sieve[p]:
            sieve[p*p::p] = b'\x01'*((root-p*p)//p+1)
    primes = [p for p in range(2, root+1) if not sieve[p]]
    values = [N//i for i in range(1, root+1)]
    values.extend(range(N//(root+1), 0, -1))
    size = len(values)
    one = [(v-1)//3 for v in values]
    two = [(v+1)//3 for v in values]
    before_one = before_two = 0
    for p in primes:
        if p == 3:
            continue
        square = p*p
        end = size-square+1 if square <= root else N//square
        for j in range(end):
            q = values[j]//p
            k = size-q if q <= root else N//q-1
            a, b = one[k]-before_one, two[k]-before_two
            if p % 3 == 1:
                one[j] -= a
                two[j] -= b
            else:
                one[j] -= b
                two[j] -= a
        if p % 3 == 1:
            before_one += 1
        else:
            before_two += 1
    prefix = [0]
    for p in primes:
        prefix.append(prefix[-1]+(p % 3 != 2))
    weights = [1]
    for e in range(1, N.bit_length()):
        weights.append(weights[-1]*(M+e-1)*pow(e, mod-2, mod) % mod)

    def sums(x, first):
        k = size-x if x <= root else N//x-1
        total = M*(one[k]+two[k]+(x >= 3)-first)
        bad = M*(one[k]+(x >= 3)-prefix[first])
        for i in range(first, len(primes)):
            p = primes[i]
            if p*p > x:
                break
            q = x//p
            e = 1
            residue = p % 3
            while q >= p:
                if i+1 == len(primes) or primes[i+1]**2 > q:
                    k = size-q if q <= root else N//q-1
                    ct = M*(one[k]+two[k]+(q >= 3)-i-1)
                    cb = M*(one[k]+(q >= 3)-prefix[i+1])
                else:
                    ct, cb = sums(q, i+1)
                total += weights[e]*ct+weights[e+1]
                if residue == 0 or (residue == 1 and e % 3 != 2) or (residue == 2 and e % 2 == 0):
                    bad += weights[e]*cb
                if residue == 0 or (residue == 1 and (e+1) % 3 != 2) or (residue == 2 and (e+1) % 2 == 0):
                    bad += weights[e+1]
                q //= p
                e += 1
        return total % mod, bad % mod
    total, bad = sums(N, 0)
    return (total-bad) % mod


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive integer sequences whose product is <= N
    and whose product has divisor sum divisible by 3, modulo 998244353.

    Bounds: 1 <= N <= 10**10, 1 <= M <= 10**5.
    Prime powers contribute C(M+e-1,e) sequences. We subtract products
    with nonzero divisor sum modulo 3 from the unrestricted total.
    """
    if N < 2:
        return 0
    if N >= 10000:
        kernel = _load_kernel()
        if kernel is not None:
            return kernel.count_sequences(N, M)
    return _python_count(N, M)

