    # Keys contain occupancies of the four states and the current state.
    dp = {(1, 0, 0, 0, 0): 1}
    letters = {'A': (1,), 'B': (2,), 'C': (3,), '?': (1, 2, 3)}
    for ch in s:
        nxt = {}
        for (a, b, c, d, current), ways in dp.items():
            for letter in letters[ch]:
                end = current ^ letter
                if end == 0:
                    key = (a + 1, b, c, d, end)
                elif end == 1:
                    key = (a, b + 1, c, d, end)
                elif end == 2:
                    key = (a, b, c + 1, d, end)
                else:
                    key = (a, b, c, d + 1, end)
                nxt[key] = (nxt.get(key, 0) + ways) % mod
        dp = nxt

    answer = 0
    for (a, b, c, d, _), ways in dp.items():
        good = (a * (a - 1) + b * (b - 1) +
                c * (c - 1) + d * (d - 1)) // 2
        if good >= k:
            answer += ways
    return answer % mod

